  async function reminders() { const d = await ready(); const out = []; const at9 = (iso, minusDays) => { const t = new Date(iso + "T09:00"); t.setDate(t.getDate() - (minusDays || 0)); return t; }; for (const c of d.compliance) { if (!c.expires) continue; const vn = (vessel(c.vesselId) || {}).name || "Vessel"; out.push({ id: "ps-c30-" + c.id, at: at9(c.expires, 30), title: vn + ": " + c.name + " expires in 30 days", body: "Expires " + fmtD(c.expires) + " · PROSHIP → Compliance" }); out.push({ id: "ps-c0-" + c.id, at: at9(c.expires, 0), title: vn + ": " + c.name + " expires today", body: "PROSHIP → Compliance" }); } for (const f of d.fixtures) if (["fixed", "delivered"].includes(f.status) && f.redelivery && f.redelivery.at) out.push({ id: "ps-red-" + f.id, at: new Date(new Date(f.redelivery.at).getTime() - 7 * 86400000), title: ((vessel(f.vesselId) || {}).name || "Vessel") + ": redelivery in 7 days", body: fmtDT(f.redelivery.at) + (f.redelivery.port ? " · " + f.redelivery.port : "") + (f.redelivery.estimated ? " (estimated)" : "") }); return out; }
  async function search(q2) { const d = await ready(); q2 = (q2 || "").toLowerCase(); const out = []; for (const v of vessels()) if ((v.name || "").toLowerCase().includes(q2) || String(v.imo || "").includes(q2)) out.push({ l: v.name, d: "Vessel · " + [v.type, v.imo ? "IMO " + v.imo : null].filter(Boolean).join(" · "), fn: () => SUITE.open("proship", { vessel: v.id, tab: "commercial" }) }); for (const f of d.fixtures) if (cpName(f.chartererCpId).toLowerCase().includes(q2) || (f.delivery && (f.delivery.port || "").toLowerCase().includes(q2)) || (f.cpForm || "").toLowerCase().includes(q2)) out.push({ l: ((vessel(f.vesselId) || {}).name || "") + " · " + kindName(f.kind) + " to " + cpName(f.chartererCpId), d: "Fixture · " + rateText(f), fn: () => SUITE.open("proship", { vessel: f.vesselId, tab: "commercial", sel: { kind: "fixture", id: f.id } }) }); for (const vy of d.voyages) if ((vy.ports || []).some((p) => (p.name || "").toLowerCase().includes(q2))) out.push({ l: ((vessel(vy.vesselId) || {}).name || "") + " · voyage " + (vy.no || ""), d: (vy.ports || []).map((p) => p.name).join(" → "), fn: () => SUITE.open("proship", { vessel: vy.vesselId, tab: "commercial", sub: "voyages", sel: { kind: "voyage", id: vy.id } }) }); return out.slice(0, 8); }
  // 4.32 · the help reads the way the app is laid out now: four places, her page, + New, the search
  const help = () => [["Four places", "Fleet (overview, live map, vessels), Commercial (fixtures, voyages, next open, strategy, customers), Operations (board, noon reports, port calls, positions, bunkers, off-hire, claims & compliance) and Finance (P&L, invoices & payments, statement of accounts, voyage P&L, DAs, cash flow, performance, reports). The sections of a place are the list on the left; Showing, under it, is the one filter every place follows."], ["Her page", "A vessel's name — in the list, the inspector, a table or the search — opens her page: everything about her on one scrolling page (overview, employment, voyages, noon reports, bunkers, invoices & payments, off-hire & claims, compliance, documents, notes & contacts) with an index on the left. ← goes back to where you came from."], ["+ New", "Everything you can record, grouped by place: fixtures and voyages, noon and position reports, port calls, stems, off-hire, claims, DAs, tasks, invoices, expenses, receipts and payments, onboarding a vessel, a contact. The vessel in view is preselected. The n key opens it."], ["Search", "Finds a vessel, a fixture, a voyage number, an invoice ref, a port, a counterparty, a contact or a note; arrows and Enter open it. While you type, the list on the page is filtered too. The / key focuses it."], ["Vessels", "Onboard with + New: IMO, particulars, speeds and consumption. A vessel already in ACCOUNTING is picked from the list; otherwise she is created there too."], ["Fixtures", "+ New › Fixture is the recap: charterer, rate, commissions, delivery and redelivery to the minute, bunkers, cargo and laytime. Mark delivered/redelivered from the row's ⋯."], ["Voyages", "Ports in order, legs with great-circle distances via Suez, Panama or the Cape, speeds, days and bunker consumption; port calls and ROB live under Operations."], ["Employment", "Her page › Employment: the timeline, the charter party in force with its warranties and options, the rate against the market, the charterers, redelivery planning, subjects and options with deadlines, addenda and the pipeline. Commercial › Next open is the fleet's: open positions by month and area and the exposure per charterer."], ["Operations", "The procedure runs itself: Pre-fixture → Pre-delivery → Port calls → Daily noon reports → Bunkering → Off-hire → Redelivery → Claims. Items tick themselves off from the data you enter (a noon report, a port call's NOR, a bunker delivery, an invoice); tick the rest by hand. The board shows what is overdue, due today and this week across the fleet."], ["Off-hire", "From/to to the minute, and its kind: technical (she is not available — dry dock, repairs, breakdown, survey, crew, guarantee works, detention) or commercial (available but not earning — waiting, idle, positioning). Deductible off-hire comes off the hire statement. Two utilisation rates follow: total = employed days over all days under management; commercial = employed days over the days available (technical off-hire left out) — the commercial manager's own figure. Rows recorded before 4.31.11 show their kind as inferred from the reason until you confirm it."], ["Map", "Fleet › Live map shows every vessel's last position (AIS when linked, otherwise your position reports) and the selected voyage's route."], ["Customers", "Owners and charterers are counterparties; assign them vessels and give them a portal login under the gear › Portal."], ["Strategy", "A plan per vessel and horizon: target rate, markets, cargoes, relocation — compared with the current fixture and the market."], ["Claims & compliance", "Certificates, vetting, PSC and insurance with expiry warnings 60 days ahead; sanctions screening from the books; the claims against charterers and others."], ["Gear", "Settings (map, fleet currency, market rates, positions), Portal, Reload from cloud, About / Rendering."], ["Phone", "The bottom bar holds the four places around Home; the sections are the chip row on top of the page; + New floats above the bar; search and the gear are in the header."]];
